function effectFilter(){const e=Zuxcyn.effects;return `blur(${e.blur}px) brightness(${e.brightness}%) contrast(${e.contrast}%) grayscale(${e.grayscale}%) sepia(${e.sepia}%) saturate(${e.saturate}%) hue-rotate(${e.hue}deg)`}
function renderEffects(){const f=effectFilter();["videoStage","imageStage"].forEach(id=>$(id).style.filter=f);const active=new Set;const e=Zuxcyn.effects;if(e.blur)active.add("blur");if(e.brightness!==100)active.add("brightness");if(e.contrast!==100)active.add("contrast");if(e.grayscale)active.add("grayscale");if(e.sepia)active.add("sepia");if(e.saturate!==100)active.add("saturate");if(e.hue)active.add("hue");if(e.glow)active.add("glow");document.querySelectorAll(".effect-card").forEach(b=>b.classList.toggle("active",active.has(b.dataset.effect)));const glow=e.glow?`drop-shadow(0 0 12px rgba(174,84,255,.9)) drop-shadow(0 0 25px rgba(95,70,255,.7))`:"";["videoStage","imageStage"].forEach(id=>$(id).style.filter=f+" "+glow)}
function applyEffect(name){commit();const e=Zuxcyn.effects;if(name==="blur")e.blur=e.blur?0:6;if(name==="brightness")e.brightness=e.brightness===100?125:100;if(name==="contrast")e.contrast=e.contrast===100?130:100;if(name==="grayscale")e.grayscale=e.grayscale?0:100;if(name==="sepia")e.sepia=e.sepia?0:100;if(name==="saturate")e.saturate=e.saturate===100?170:100;if(name==="hue")e.hue=e.hue?0:90;if(name==="glow")e.glow=e.glow?0:1;renderEffects();toast(name+" effect diterapkan")}
document.addEventListener("DOMContentLoaded",()=>{document.querySelectorAll(".effect-card").forEach(b=>b.onclick=()=>applyEffect(b.dataset.effect));$("resetEffectsBtn").onclick=()=>{commit();Zuxcyn.effects={blur:0,brightness:100,contrast:100,grayscale:0,sepia:0,saturate:100,hue:0,glow:0};renderEffects();toast("Effects direset")};renderEffects()});
